# frozen_string_literal: true

# Adwaita as Tailwind v4's own language, generated by bin/03-adwaita-tailwind.
#
# THE POINT IS THAT A TOKEN BECOMES A UTILITY. A variable in `:root` is a variable:
# `bg-[var(--accent-bg-color)]` is an arbitrary value, opaque to tailwind-merge, which is why
# a colour set by one class kept being dropped by the class beside it. The same variable in
# `@theme` generates `bg-accent-bg`, which tailwind-merge knows is a background and merges
# against the other backgrounds.
#
# Four things, each read from a source rather than typed out here:
#
#   @theme           the palette, the radii, the easing and the container sizes.
#   :root overrides  the dark palette. `@theme` is top-level only, and the utilities emit
#                    `var(--color-…)`, so redefining the variable under a selector repoints
#                    every utility that reads it. That is what keeps the palette overridable,
#                    and the reason not to use `@theme inline`.
#   @custom-variant  the states, the alignment attributes and the node paths, which the
#                    component generator would otherwise write out by hand thousands of times.
#   @utility         the layout managers, read out of GTK's and libadwaita's C.
#
# LAYOUT IS NOT IN THE STYLESHEET. GTK's CSS has no `display`, so no amount of reading the
# sheet produces one: the manager is in the C, as the type each widget class passes to
# gtk_widget_class_set_layout_manager_type(). That is why this reads the source tree.
module Theme
  ROOT = File.expand_path("../..", __dir__)

  SOURCE = "bin/02-fetch-gir.out/src"

  # A variable's name against the namespace Tailwind generates utilities from. The suffix
  # libadwaita puts on every one of these -- `-color`, `-bg-color` -- is noise once the
  # namespace says what it is, so `--accent-bg-color` is `--color-accent-bg` and the utility
  # is `bg-accent-bg` rather than `bg-accent-bg-color`.
  COLOUR_SUFFIX = /-color\z/.freeze

  # The namespaces, and what goes in each. Tailwind reads the prefix and nothing else:
  # `--color-*` makes `bg-*`/`text-*`/`border-*`, `--radius-*` makes `rounded-*`, and a name
  # under no namespace is a variable like any other and generates nothing.
  #
  # ON THE SIZES. AdwClamp's maximum is a width a page is held to and AdwBreakpoint's
  # condition is a width a widget is measured against, which is `--container-*`: the same
  # number drives `max-w-*` and the `@sm:`/`@max-sm:` container queries, and a breakpoint
  # that is a property of the widget is a container query rather than a media query.
  def self.theme(variables, radii, easing)
    sections = []

    sections << self.colours(variables.fetch("light"))
    sections << self.accent
    sections << self.lengths("radius", radii)
    sections << self.lengths("container", self.containers)
    sections << easing

    sections.reject(&:empty?)
  end

  # The accent, which is the one colour that is not in the stylesheet.
  #
  # `--accent-bg-color` is a runtime setting rather than a declaration: the sheet reads it
  # and never states it, so bin/03 -- which reads the sheet -- cannot see it, and the single
  # most-used colour in the toolkit was missing from the palette. It is in the C, as the
  # table adw_accent_color_to_rgba() switches over, and that is where this reads it.
  #
  # ADW_ACCENT_COLOR_BLUE is the default, so it is what `--color-accent-bg` resolves to; the
  # rest are tokens of their own, which is what makes `bg-accent-purple` a utility.
  def self.accent
    path = File.join(ROOT, SOURCE, "libadwaita/src/adw-accent-color.c")

    return [] unless File.exist?(path)

    found = File.read(path).scan(/case ADW_ACCENT_COLOR_([A-Z]+):\s*\n\s*hex = "(#[0-9a-fA-F]{6})";/)

    return [] if found.empty?

    default = found.first.last

    [
      # Through libadwaita's own names, for the reason given above; the hex read out of the
      # C is what variables.css gives those names when the sheet does not.
      ["--color-accent-bg", "var(--accent-bg-color, #{default})"],
      ["--color-accent-fg", "var(--accent-fg-color, #ffffff)"],
    ]
  end

  # Every colour, as `--color-*`.
  #
  # A value which is another variable is kept as the reference it is: `--destructive-bg-color:
  # var(--red-3)` stays pointing at `--red-3`, so repointing the palette at a brand still
  # moves everything downstream of it.
  def self.colours(light)
    light.filter_map do |name, value|
      next unless self.colour?(value)

      # AN ALIAS AND NOT A COPY. A custom property is substituted where it is DECLARED, so
      # `--color-accent: oklab(from var(--accent-bg-color) …)` written here resolves
      # `--accent-bg-color` at `:root` and freezes it. Adwaita's whole mechanism is the
      # opposite: `.destructive-action` redefines `--accent-bg-color` on the element and
      # everything under it re-resolves, which is how a destructive button goes red without
      # a single rule mentioning red. Frozen at `:root`, the remap could not reach the token
      # and a destructive button came out in the accent's blue.
      #
      # Pointing the token AT libadwaita's own variable keeps the indirection: `bg-accent-bg`
      # is `var(--color-accent-bg)` is `var(--accent-bg-color)`, resolved at the element.
      ["--color-#{self.token(name)}", "var(#{name})"]
    end
  end

  # A value is a colour when it reads as one. The palette holds a handful of things which are
  # not -- opacities, the oklab expression the standalone colours are derived through -- and
  # those are variables rather than tokens: there is no utility for an opacity.
  def self.colour?(value)
    string = value.to_s.strip

    return false if string.empty?
    return true if string.start_with?("#")
    return true if string.match?(/\A(rgba?|hsla?|oklab|oklch|color-mix|hsl)\(/i)
    return true if %w[white black transparent currentColor].include?(string)

    # `var(--red-3)` is a colour when what it points at is one, which for this palette it is:
    # the only variables a colour is stated as are the named shades.
    string.match?(/\Avar\(--[a-z]+-\d\)\z/)
  end

  # The name a variable is addressed by, once the namespace has said what kind it is.
  def self.token(name)
    name.sub(/\A--/, "").sub(COLOUR_SUFFIX, "")
  end

  def self.lengths(namespace, values)
    values.map{|name, value| ["--#{namespace}-#{name}", value] }
  end

  # AdwClamp's maximum and the widths AdwBreakpoint is written against, as container sizes.
  # These are the numbers the toolkit's own widgets use: a preferences page clamps at 600,
  # a status page at 450, and the adaptive breakpoints in the wild are 400/600/800.
  def self.containers
    [["clamp", "600px"], ["clamp-narrow", "450px"], ["clamp-wide", "800px"]]
  end

  # The radii, read out of the stylesheet's SCSS rather than restated. `$dialog_radius:
  # $button_radius + 6` is arithmetic in a variable, so the sheet is read for the numbers and
  # the expressions are resolved against what has already been read.
  def self.radii
    scss = self.scss
    found = {}

    scss.scan(/\$_?([a-z_]*radius[a-z_]*): *([^;]+);/) do |name, value|
      found[name] = value.strip
    end

    resolved = {}

    found.each do |name, value|
      number = self.length(value, found)

      next if number.nil?

      resolved[name.sub(/_?radius_?/, "").sub(/\A_/, "").sub(/_\z/, "").tr("_", "-")] = number
    end

    resolved.reject{|name, _value| name.empty? }.sort.to_h
  end

  # A SCSS length, which is either a number of pixels or one plus another variable's.
  def self.length(value, found)
    return "#{Regexp.last_match(1)}px" if value.match(/\A(\d+)px\z/)

    if value.match(/\A\$([a-z_]+) *\+ *(\d+)\z/)
      base = found[Regexp.last_match(1)]
      offset = Regexp.last_match(2).to_i

      return nil if base.nil? || !base.match(/\A(\d+)px\z/)

      return "#{Regexp.last_match(1).to_i + offset}px"
    end

    nil
  end

  # The one curve and the one duration libadwaita animates on, which is the difference
  # between a port that feels right and one that does not.
  def self.easing
    [
      ["--ease-adwaita", "cubic-bezier(0.25, 0.46, 0.45, 0.94)"],
      ["--ease-adwaita-out", "ease-out"],
      ["--animate-duration-adwaita", "200ms"],
    ]
  end

  # Every .scss libadwaita states its own metrics in, as one string.
  def self.scss
    Dir.glob(File.join(ROOT, SOURCE, "libadwaita/src/stylesheet/**/*.scss")).sort.map do |path|
      File.read(path)
    end.join("\n")
  end

  # The layout manager each widget class names, out of the C.
  #
  #     gtk_widget_class_set_layout_manager_type (widget_class, GTK_TYPE_BOX_LAYOUT);
  #
  # This is the fact the stylesheet does not carry and cannot: GTK's CSS has no `display`,
  # so what arranges a widget's children is only ever stated here.
  def self.managers
    found = Hash.new{|hash, key| hash[key] = [] }

    Dir.glob(File.join(ROOT, SOURCE, "{gtk/gtk,libadwaita/src}/**/*.c")).sort.each do |path|
      source = File.read(path)

      source.scan(/set_layout_manager_type *\([^;]*?([A-Z][A-Z0-9_]*_TYPE_[A-Z0-9_]*LAYOUT)/m) do |type|
        found[type.first] << File.basename(path, ".c")
      end
    end

    found
  end

  # What each manager does, as CSS. One rule per manager, and the widget names it.
  #
  # GTK's managers are few and each is a paragraph: a box distributes along one axis, a bin
  # hands its child the whole allocation, a centre layout is three slots of which the middle
  # is centred against the whole and not against what is left. The web has all three; what it
  # does not have is GTK's defaults, which is why each of these also states the alignment and
  # expansion plumbing the toolkit applies without being asked.
  LAYOUTS = {
    "GTK_TYPE_BOX_LAYOUT" => {
      "name" => "box-layout",
      "body" => <<~CSS,
        /* The axis is NOT stated here. GTK puts `.horizontal` or `.vertical` on every
         * orientable widget and the component writes whichever it was given, so stating a
         * direction here too is two rules setting one property and the cascade -- not the
         * generator -- deciding between them. */
        display: flex;

        /* GTK's children fill the cross axis unless they say otherwise, which is
         * `stretch` and not the `flex-start` a bare flex container would give them. */
        align-items: stretch;
      CSS
    },
    "GTK_TYPE_BIN_LAYOUT" => {
      "name" => "bin-layout",
      "body" => <<~CSS,
        /* A bin hands its child the whole allocation, which is one cell every child is
         * placed into rather than a column they are stacked in: GtkOverlay and every
         * widget with no manager of its own put their children on top of each other. */
        display: grid;
        grid-template-areas: "bin";

        & > * {
          grid-area: bin;
          min-width: 0;
          min-height: 0;
        }
      CSS
    },
    "GTK_TYPE_CENTER_LAYOUT" => {
      "name" => "center-layout",
      "body" => <<~CSS,
        /* THE CENTRE IS CENTRED AGAINST THE WHOLE. Three columns of which the outer two
         * are equal is what puts the middle child in the middle of the widget rather than
         * in the middle of what the other two left over, which is a header bar's title
         * sitting off to one side as soon as one end has more buttons than the other. */
        display: grid;
        grid-template-columns: 1fr auto 1fr;
        align-items: center;

        & > *:first-child { justify-self: start; }
        & > *:last-child { justify-self: end; }
      CSS
    },
    "GTK_TYPE_OVERLAY_LAYOUT" => {
      "name" => "overlay-layout",
      "body" => <<~CSS,
        display: grid;
        grid-template-areas: "overlay";

        & > * {
          grid-area: overlay;
          min-width: 0;
          min-height: 0;
        }
      CSS
    },
    "GTK_TYPE_GRID_LAYOUT" => {
      "name" => "grid-layout",
      "body" => "display: grid;\n"
    },
    "GTK_TYPE_FIXED_LAYOUT" => {
      "name" => "fixed-layout",
      "body" => "position: relative;\n\n& > * { position: absolute; }\n"
    },
    "ADW_TYPE_CLAMP_LAYOUT" => {
      "name" => "clamp-layout",
      "body" => <<~CSS,
        /* A clamp is a column of one thing, held to a maximum and centred in whatever it
         * is given. Three columns rather than `margin: auto` so that a child which wants
         * the full width still gets the full width. */
        display: grid;
        grid-template-columns: 1fr minmax(0, var(--container-clamp)) 1fr;

        & > * { grid-column: 2; min-width: 0; }
      CSS
    },
    "ADW_TYPE_WRAP_LAYOUT" => {
      "name" => "wrap-layout",
      "body" => "display: flex;\nflex-wrap: wrap;\n"
    },
  }.freeze

  # The arrangements which are not a GtkLayoutManager but which the registry needs a name
  # for anyway: a scrolled window's viewport, a split view's two tracks, a grid view's
  # columns. GTK does these in each widget's own measure and allocate rather than through a
  # manager, so there is no `set_layout_manager_type` to read them out of -- but they are
  # arrangements like the others and belong beside them rather than spliced into a string.
  COMPOSITES = {
    "fill-layout" => <<~CSS,
      /* The widget takes the whole of what it is given. `min-height: 0` is what lets it:
       * a flex item will not shrink below its content without it, so a scroller in a page
       * pushed the page open instead of scrolling. */
      display: flex;
      flex-direction: column;
      flex-grow: 1;
      min-height: 0;
    CSS
    "scroll-layout" => <<~CSS,
      /* The same, and what will not fit is scrolled rather than pushing the page open.
       *
       * A CHILD WHICH ALIGNS ITSELF IS NOT STRETCHED. Growing every child made
       * AdwStatusPage's box as tall as the viewport with its contents at the top, which is
       * the icon, title and button of every status page 115px above where the toolkit puts
       * them. Where such a child sits is stated on the container and never as a margin on
       * the child: `margin: auto` centres it too, and it replaced the status page's own
       * `my-9`. */
      display: flex;
      flex-direction: column;
      flex-grow: 1;
      min-height: 0;
      overflow: auto;

      & > *:not([data-valign]) { flex-grow: 1; min-height: 0; }
      &:has(> [data-valign="center"]) { justify-content: center; }
      &:has(> [data-valign="end"]) { justify-content: flex-end; }
      &:has(> [data-valign="start"]) { justify-content: flex-start; }
    CSS
    "split-layout" => <<~CSS,
      /* The sidebar's track and the content's. The widths are a fraction of the whole
       * clamped between a minimum and a maximum, which a grid cannot stateand lib/split-view.ts
       * works out. */
      display: grid;

      & > * { min-width: 0; }
    CSS
    "fill-grid-layout" => <<~CSS,
      /* Items across, wrapped, packed to the top of whatever height the view is given. */
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(96px, 1fr));
      align-content: start;
      flex-grow: 1;
      min-height: 0;
    CSS
  }.freeze

  # The alignment and expansion GTK applies to a container's children without being asked.
  # One utility rather than seven classes on every container: a grid track is as tall as its
  # tallest child unless the child may shrink, and GTK's children all may.
  ALIGNMENT = <<~CSS
    & > * { min-height: 0; }
    & > [data-halign="start"] { justify-self: start; }
    & > [data-halign="center"] { justify-self: center; }
    & > [data-halign="end"] { justify-self: end; }
    & > [data-valign="start"] { align-self: start; }
    & > [data-valign="center"] { align-self: center; }
    & > [data-valign="end"] { align-self: end; }
  CSS


  # The variants, which are the selectors bin/11 would otherwise write out by hand.
  #
  # A node path, an alignment, an expansion and a state are each one shape repeated: the
  # table holds 8,274 `:where([data-node=…])` strings and 390 alignment selectors, every one
  # of them built by string concatenation at generation time. Declared here they are built
  # once, by Tailwind, and a component writes `node-box:pt-2` instead.
  def self.variants
    found = []

    # The states GTK puts on a widget, as the DOM carries them.
    found << ["gtk-hover", "&:hover"]
    found << ["gtk-active", "&:active"]
    found << ["gtk-disabled", '&:is(:disabled, [data-disabled], [aria-disabled="true"])']
    found << ["gtk-checked", '&:is(:checked, [data-state="checked"], [aria-checked="true"])']
    found << ["gtk-selected", '&:is([data-selected], [aria-selected="true"])']
    found << ["gtk-focus", "&:focus-visible"]
    found << ["gtk-backdrop", "&:where([data-backdrop] *)"]
    found << ["gtk-flat", "&:where(.flat)"]

    # The alignment and expansion a child was given, read by the container that knows which
    # way it runs. `halign` is horizontal whichever way the parent goes and `align-self` is
    # whichever way it does not, so the container resolves it rather than the child.
    %w[start center end baseline].each do |align|
      found << ["child-h#{align}", "& > :where([data-halign=\"#{align}\"])"]
      found << ["child-v#{align}", "& > :where([data-valign=\"#{align}\"])"]
    end

    found << ["child-hexpand", "& > :where([data-hexpand])"]
    found << ["child-vexpand", "& > :where([data-vexpand])"]

    found
  end

  # A variant per CSS node, which is what every contextual rule in the table reaches through.
  def self.node_variants(nodes)
    nodes.sort.flat_map do |node|
      [
        ["node-#{node}", "& > :where([data-node=\"#{node}\"])"],
        ["in-#{node}", "& :where([data-node=\"#{node}\"])"],
      ]
    end
  end

  def self.render(nodes, variables)
    out = []

    out << <<~HEAD
      /* Generated by bin/19-tailwind-theme. Do not edit.
       *
       * Adwaita as Tailwind v4 language: the palette as theme tokens, the states and the node
       * paths as variants, and the layout managers -- which are in GTK's C and in no
       * stylesheet anywhere -- as utilities.
       *
       * Imported by adwaita.css before anything else, because a utility a component names has
       * to exist before the component is read.
       */
    HEAD

    theme = self.theme(variables, self.radii, self.easing)

    out << "/* `inline`, which is what makes the remap work."
    out << " *"
    out << " * Without it a utility emits `var(--color-accent)` and the token is a declaration on"
    out << " * `:root` -- and a custom property is substituted where it is DECLARED, so the alias"
    out << " * freezes to the root's accent no matter what an element below redefines. `inline`"
    out << " * puts the token's VALUE in the utility instead, so `text-accent` compiles to"
    out << " * `color: var(--accent-color)` and resolves at the element. That is how"
    out << " * `.destructive-action` -- which redefines `--accent-color` on itself -- turns a"
    out << " * button red without a single rule mentioning red. */"
    out << "@theme inline static {"
    theme.each_with_index do |section, index|
      out << "" if index.positive?
      section.each{|name, value| out << "  #{name}: #{value};" }
    end
    out << "}"
    out << ""

    out << self.dark(variables)
    out << ""

    out << "/* The states, the alignments and the node paths. */"
    (self.variants + self.node_variants(nodes)).each do |name, selector|
      out << "@custom-variant #{name} (#{selector});"
    end
    out << ""

    out << self.layouts

    out.join("\n")
  end

  # The dark palette, as overrides rather than as a second theme: the utilities emit
  # `var(--color-…)`, so redefining the variable under a selector moves every utility that
  # reads it without generating a single extra class.
  def self.dark(variables)
    dark = variables.fetch("dark", {}).filter_map do |name, value|
      next unless self.colour?(value)

      # LIBADWAITA'S OWN NAME, not the token's. The tokens are aliases of these, so moving
      # the variable moves every utility that reads it; writing the token instead would
      # replace the alias with a value and break the remap the light palette relies on.
      "  #{name}: #{value};"
    end

    return "" if dark.empty?

    [
      "/* The dark palette, as libadwaita's own variables. The tokens above alias these, so",
      " * repointing them here moves every `bg-*` and `text-*` generated from them. */",
      "@media (prefers-color-scheme: dark) {",
      "  :root:not([data-theme=\"light\"]) {",
      dark.map{|line| "  #{line}" },
      "  }",
      "}",
      "",
      ":root[data-theme=\"dark\"] {",
      dark,
      "}",
    ].flatten.join("\n")
  end

  def self.layouts
    out = ["/* The layout managers, read out of GTK's and libadwaita's C. */"]

    found = self.managers

    LAYOUTS.each do |type, layout|
      widgets = found[type]

      out << ""
      out << "/* #{type} -- #{widgets.length} widget#{'s' unless widgets.length == 1}#{": #{widgets.sort.take(4).join(', ')}#{'…' if widgets.length > 4}" unless widgets.empty?} */"
      out << "@utility #{layout.fetch('name')} {"
      out.concat(self.indented(layout.fetch("body")))
      out << "}"
    end

    # The arrangements GTK does in each widget's own measure and allocate rather than
    # through a manager, so there is no `set_layout_manager_type` to read them out of.
    COMPOSITES.each do |name, body|
      out << ""
      out << "@utility #{name} {"
      out.concat(self.indented(body))
      out << "}"
    end

    out << ""
    out << "/* What GTK gives a container's children without being asked. */"
    out << "@utility gtk-alignment {"
    out.concat(self.indented(ALIGNMENT))
    out << "}"

    out.join("\n")
  end

  def self.indented(body)
    body.lines.map{|line| line.strip.empty? ? "" : "  #{line.chomp}" }
  end



  # The whole file.
  def self.css(nodes, variables)
    "#{self.render(nodes, variables).rstrip}\n"
  end
end
